30	MambaCacheManager::MambaCacheManager(Config const& config, cudaStream_t stream)
31	    : mConfig(config)
32	{
33	    if (mConfig.numRecurrentLayers == 0)
34	    {
35	        return;
36	    }
37	
38	    check::check(mConfig.maxBatchSize > 0, "maxBatchSize must be positive.");
39	    check::check(mConfig.recurrentStateNumHeads > 0, "recurrentStateNumHeads must be positive.");
40	    check::check(mConfig.recurrentStateHeadDim > 0, "recurrentStateHeadDim must be positive.");
41	    check::check(mConfig.recurrentStateSize > 0, "recurrentStateSize must be positive.");
42	    check::check(mConfig.convDim > 0, "convDim must be positive.");
43	    check::check(mConfig.convKernel > 0, "convKernel must be positive.");
44	
45	    size_t totalBytes = 0;
46	    size_t const recurrentElemSize = rt::utils::getTypeSize(mConfig.recurrentStateType);
47	    size_t const convElemSize = rt::utils::getTypeSize(mConfig.convStateType);
48	
49	    mRecurrentStates.reserve(mConfig.numRecurrentLayers);
50	    mConvStates.reserve(mConfig.numRecurrentLayers);
51	
52	    for (int32_t i = 0; i < mConfig.numRecurrentLayers; ++i)
53	    {
54	        // Allocate recurrent state: [maxBatchSize, numHeads, headDim, stateSize]
55	        int64_t const recurrentVolume = static_cast<int64_t>(mConfig.maxBatchSize) * mConfig.recurrentStateNumHeads
56	            * mConfig.recurrentStateHeadDim * mConfig.recurrentStateSize;
57	        size_t const recurrentBytes = static_cast<size_t>(recurrentVolume) * recurrentElemSize;
58	
59	        mRecurrentStates.emplace_back(rt::Tensor({mConfig.maxBatchSize, mConfig.recurrentStateNumHeads,
60	                                                     mConfig.recurrentStateHeadDim, mConfig.recurrentStateSize},
61	            DeviceType::kGPU, mConfig.recurrentStateType, "MambaCacheManager::recurrentState_" + std::to_string(i)));
62	        CUDA_CHECK(cudaMemsetAsync(mRecurrentStates.back().rawPointer(), 0, recurrentBytes, stream));
63	
64	        // Allocate conv state: [maxBatchSize, convDim, convKernel]
65	        int64_t const convVolume = static_cast<int64_t>(mConfig.maxBatchSize) * mConfig.convDim * mConfig.convKernel;
66	        size_t const convBytes = static_cast<size_t>(convVolume) * convElemSize;
67	
68	        mConvStates.emplace_back(rt::Tensor({mConfig.maxBatchSize, mConfig.convDim, mConfig.convKernel},
69	            DeviceType::kGPU, mConfig.convStateType, "MambaCacheManager::convState_" + std::to_string(i)));
70	        CUDA_CHECK(cudaMemsetAsync(mConvStates.back().rawPointer(), 0, convBytes, stream));
71	
72	        totalBytes += recurrentBytes + convBytes;
73	    }
74	
75	    // Allocate spec-verify intermediate state buffers when enabled (maxIntermediateSeqLen > 0).
76	    if (mConfig.maxIntermediateSeqLen > 0)
77	    {
78	        mIntermediateRecurrentStates.reserve(mConfig.numRecurrentLayers);
79	        mIntermediateConvStates.reserve(mConfig.numRecurrentLayers);
80	
81	        for (int32_t i = 0; i < mConfig.numRecurrentLayers; ++i)
82	        {
83	            int64_t const intermRecVolume = static_cast<int64_t>(mConfig.maxBatchSize) * mConfig.maxIntermediateSeqLen
84	                * mConfig.recurrentStateNumHeads * mConfig.recurrentStateHeadDim * mConfig.recurrentStateSize;
85	            size_t const intermRecBytes = static_cast<size_t>(intermRecVolume) * recurrentElemSize;
86	
87	            mIntermediateRecurrentStates.emplace_back(
88	                rt::Tensor({mConfig.maxBatchSize, mConfig.maxIntermediateSeqLen, mConfig.recurrentStateNumHeads,
89	                               mConfig.recurrentStateHeadDim, mConfig.recurrentStateSize},
90	                    DeviceType::kGPU, mConfig.recurrentStateType,
91	                    "MambaCacheManager::intermediateRecurrentState_" + std::to_string(i)));
92	            CUDA_CHECK(cudaMemsetAsync(mIntermediateRecurrentStates.back().rawPointer(), 0, intermRecBytes, stream));
93	
94	            int64_t const intermConvVolume = static_cast<int64_t>(mConfig.maxBatchSize) * mConfig.maxIntermediateSeqLen
95	                * mConfig.convDim * mConfig.convKernel;
96	            size_t const intermConvBytes = static_cast<size_t>(intermConvVolume) * convElemSize;
97	
98	            mIntermediateConvStates.emplace_back(
99	                rt::Tensor({mConfig.maxBatchSize, mConfig.maxIntermediateSeqLen, mConfig.convDim, mConfig.convKernel},
100	                    DeviceType::kGPU, mConfig.convStateType,
101	                    "MambaCacheManager::intermediateConvState_" + std::to_string(i)));
102	            CUDA_CHECK(cudaMemsetAsync(mIntermediateConvStates.back().rawPointer(), 0, intermConvBytes, stream));
103	
104	            totalBytes += intermRecBytes + intermConvBytes;
105	        }
106	
107	        // Build the MtpLayerInfo array for batched spec-verify state scatter; pointers are stable, so
108	        // upload runs once.
109	        std::vector<kernel::MtpLayerInfo> hostInfos(mConfig.numRecurrentLayers);
110	        for (int32_t i = 0; i < mConfig.numRecurrentLayers; ++i)
111	        {
112	            hostInfos[i] = {
113	                mRecurrentStates[i].rawPointer(),
114	                mIntermediateRecurrentStates[i].rawPointer(),
115	                mConvStates[i].rawPointer(),
116	                mIntermediateConvStates[i].rawPointer(),
117	            };
118	        }
119	        size_t const infoBytes = hostInfos.size() * sizeof(kernel::MtpLayerInfo);
120	        mDeviceMtpLayerInfos = rt::Tensor(
121	            {static_cast<int64_t>(infoBytes)}, DeviceType::kGPU, DataType::kINT8, "MambaCacheManager::mtpLayerInfos");
122	        CUDA_CHECK(cudaMemcpyAsync(
123	            mDeviceMtpLayerInfos.rawPointer(), hostInfos.data(), infoBytes, cudaMemcpyHostToDevice, stream));
124	        // Sync before hostInfos goes out of scope.
125	        CUDA_CHECK(cudaStreamSynchronize(stream));
126	
127	        LOG_INFO("MambaCacheManager: allocated spec-verify intermediate state buffers (%d layers, maxSeqLen=%d)",
128	            mConfig.numRecurrentLayers, mConfig.maxIntermediateSeqLen);
129	    }
130	
131	    LOG_DEBUG("MambaCacheManager(layers=%d) allocated %.2f MB total GPU memory", mConfig.numRecurrentLayers,
132	        static_cast<float>(totalBytes) / (1024.0f * 1024.0f));
133	}
