175	void MambaCacheManager::clearStates(cudaStream_t stream)
176	{
177	    for (int32_t i = 0; i < mConfig.numRecurrentLayers; ++i)
178	    {
179	        CUDA_CHECK(
180	            cudaMemsetAsync(mRecurrentStates[i].rawPointer(), 0, mRecurrentStates[i].getMemoryCapacity(), stream));
