185	std::vector<rt::Tensor> MambaCacheManager::captureRecurrentStates(int32_t batchIdx, cudaStream_t stream)
186	{
187	    std::vector<rt::Tensor> result;
188	    if (mConfig.numRecurrentLayers == 0)
189	    {
190	        return result;
191	    }
192	
193	    size_t const elemSize = rt::utils::getTypeSize(mConfig.recurrentStateType);
194	    int64_t const perBatchElems
195	        = mConfig.recurrentStateNumHeads * mConfig.recurrentStateHeadDim * mConfig.recurrentStateSize;
196	    size_t const perBatchBytes = static_cast<size_t>(perBatchElems) * elemSize;
197	
198	    result.reserve(mConfig.numRecurrentLayers);
199	    for (int32_t layer = 0; layer < mConfig.numRecurrentLayers; ++layer)
200	    {
201	        void const* src = static_cast<char const*>(mRecurrentStates[layer].rawPointer())
202	            + static_cast<size_t>(batchIdx * perBatchElems) * elemSize;
203	        rt::Tensor saved({1, mConfig.recurrentStateNumHeads, mConfig.recurrentStateHeadDim, mConfig.recurrentStateSize},
204	            DeviceType::kGPU, mConfig.recurrentStateType,
205	            "MambaCacheManager::capturedRecurrentState_" + std::to_string(layer));
206	        CUDA_CHECK(cudaMemcpyAsync(saved.rawPointer(), src, perBatchBytes, cudaMemcpyDeviceToDevice, stream));
207	        result.push_back(std::move(saved));
208	    }
209	    return result;
210	}
