216	    {
217	        return result;
218	    }
219	
220	    size_t const elemSize = rt::utils::getTypeSize(mConfig.convStateType);
221	    int64_t const perBatchElems = mConfig.convDim * mConfig.convKernel;
222	    size_t const perBatchBytes = static_cast<size_t>(perBatchElems) * elemSize;
223	
224	    result.reserve(mConfig.numRecurrentLayers);
225	    for (int32_t layer = 0; layer < mConfig.numRecurrentLayers; ++layer)
226	    {
227	        void const* src = static_cast<char const*>(mConvStates[layer].rawPointer())
228	            + static_cast<size_t>(batchIdx * perBatchElems) * elemSize;
229	        rt::Tensor saved({1, mConfig.convDim, mConfig.convKernel}, DeviceType::kGPU, mConfig.convStateType,
230	            "MambaCacheManager::capturedConvState_" + std::to_string(layer));
231	        CUDA_CHECK(cudaMemcpyAsync(saved.rawPointer(), src, perBatchBytes, cudaMemcpyDeviceToDevice, stream));
232	        result.push_back(std::move(saved));
233	    }
234	    return result;
