237	void MambaCacheManager::reshapeIntermediateStates(int32_t activeBatchSize, int32_t seqLen)
238	{
239	    if (mIntermediateRecurrentStates.empty())
240	    {
241	        return;
242	    }
243	    for (int32_t i = 0; i < mConfig.numRecurrentLayers; ++i)
244	    {
245	        check::check(mIntermediateRecurrentStates[i].reshape({activeBatchSize, seqLen, mConfig.recurrentStateNumHeads,
246	                         mConfig.recurrentStateHeadDim, mConfig.recurrentStateSize}),
247	            "Intermediate recurrent state reshape failed");
248	        check::check(mIntermediateConvStates[i].reshape({activeBatchSize, seqLen, mConfig.convDim, mConfig.convKernel}),
249	            "Intermediate conv state reshape failed");
250	    }
251	}
