283	void MambaCacheManager::scatterAcceptedLinearStates(rt::Tensor const& acceptLengths, cudaStream_t stream)
284	{
285	    if (mIntermediateRecurrentStates.empty())
286	    {
287	        return;
288	    }
289	
290	    int32_t const verifySize = static_cast<int32_t>(mIntermediateRecurrentStates[0].getShape()[1]);
291	    int32_t const recElements
292	        = mConfig.recurrentStateNumHeads * mConfig.recurrentStateHeadDim * mConfig.recurrentStateSize;
293	    int32_t const convElements = mConfig.convDim * mConfig.convKernel;
294	    int32_t const activeBatchSize = static_cast<int32_t>(acceptLengths.getShape()[0]);
295	    auto const* const layerInfos = static_cast<kernel::MtpLayerInfo const*>(mDeviceMtpLayerInfos.rawPointer());
296	    int32_t const* const acceptPtr = acceptLengths.dataPointer<int32_t>();
297	
298	    kernel::mtpScatterRecurrentStates(
299	        layerInfos, mConfig.numRecurrentLayers, activeBatchSize, verifySize, recElements, acceptPtr, stream);
300	    kernel::mtpScatterConvStates(
301	        layerInfos, mConfig.numRecurrentLayers, activeBatchSize, verifySize, convElements, acceptPtr, stream);
302	}
303	
304	void MambaCacheManager::scatterAcceptedTreeStates(
305	    rt::Tensor const& acceptedStateNodeIds, rt::Tensor const& acceptLengths, cudaStream_t stream)
306	{
307	    if (mIntermediateRecurrentStates.empty())
308	    {
309	        return;
310	    }
311	
312	    check::check(!mIntermediateConvStates.empty(), "Intermediate conv states are not allocated.");
313	    check::check(mConfig.recurrentStateType == DataType::kFLOAT,
314	        "Accepted tree recurrent state scatter supports FP32 recurrent states only.");
315	    check::check(
316	        mConfig.convStateType == DataType::kHALF, "Accepted tree conv state scatter supports FP16 conv states only.");
317	    check::check(
318	        acceptedStateNodeIds.getDeviceType() == DeviceType::kGPU, "acceptedStateNodeIds must be a GPU tensor.");
319	    check::check(acceptLengths.getDeviceType() == DeviceType::kGPU, "acceptLengths must be a GPU tensor.");
320	    check::check(
321	        acceptedStateNodeIds.getDataType() == DataType::kINT32, "acceptedStateNodeIds must have INT32 data type.");
322	    check::check(acceptLengths.getDataType() == DataType::kINT32, "acceptLengths must have INT32 data type.");
323	
324	    auto const acceptedStateNodeIdsShape = acceptedStateNodeIds.getShape();
325	    auto const acceptLengthsShape = acceptLengths.getShape();
326	    check::check(
327	        acceptedStateNodeIdsShape.getNumDims() == 2, "acceptedStateNodeIds must have shape [B, maxAcceptLen].");
328	    check::check(acceptLengthsShape.getNumDims() == 1, "acceptLengths must have shape [B].");
329	
330	    int32_t const activeBatchSize = static_cast<int32_t>(acceptedStateNodeIdsShape[0]);
331	    int32_t const maxAcceptLen = static_cast<int32_t>(acceptedStateNodeIdsShape[1]);
332	    check::check(
333	        acceptLengthsShape[0] == activeBatchSize, "acceptedStateNodeIds and acceptLengths batch sizes differ.");
334	    if (activeBatchSize == 0 || maxAcceptLen == 0)
335	    {
336	        return;
337	    }
338	
339	    auto const intermediateShape = mIntermediateRecurrentStates[0].getShape();
340	    check::check(intermediateShape[0] == activeBatchSize,
341	        "Intermediate recurrent states must be reshaped to the active batch size before accepted tree scatter.");
342	    int32_t const verifyTreeSize = static_cast<int32_t>(intermediateShape[1]);
343	    int32_t const recElements
344	        = mConfig.recurrentStateNumHeads * mConfig.recurrentStateHeadDim * mConfig.recurrentStateSize;
345	    int32_t const convElements = mConfig.convDim * mConfig.convKernel;
346	    auto const* const layerInfos = static_cast<kernel::MtpLayerInfo const*>(mDeviceMtpLayerInfos.rawPointer());
347	    int32_t const* const acceptedStateNodeIdsPtr = acceptedStateNodeIds.dataPointer<int32_t>();
348	    int32_t const* const acceptLengthsPtr = acceptLengths.dataPointer<int32_t>();
349	
350	    kernel::mtpScatterAcceptedTreeRecurrentStates(layerInfos, mConfig.numRecurrentLayers, activeBatchSize,
351	        verifyTreeSize, recElements, acceptedStateNodeIdsPtr, maxAcceptLen, acceptLengthsPtr, stream);
352	    kernel::mtpScatterAcceptedTreeConvStates(layerInfos, mConfig.numRecurrentLayers, activeBatchSize, verifyTreeSize,
353	        convElements, acceptedStateNodeIdsPtr, maxAcceptLen, acceptLengthsPtr, stream);
354	}
