33	HybridCacheManager::HybridCacheManager(Config const& config, cudaStream_t stream)
34	    : mConfig(config)
35	{
36	    int32_t const totalLayers = static_cast<int32_t>(mConfig.layerTypes.size());
37	    check::check(totalLayers > 0, "HybridCacheManager: layerTypes must not be empty.");
38	    check::check(mConfig.maxBatchSize > 0, "HybridCacheManager: maxBatchSize must be positive.");
39	
40	    // Build routing tables: absolute layer index -> local sub-manager index.
41	    mAbsToKVIndex.resize(totalLayers, -1);
42	    mAbsToMambaIndex.resize(totalLayers, -1);
43	
44	    int32_t kvLocalIdx = 0;
45	    int32_t mambaLocalIdx = 0;
46	    for (int32_t i = 0; i < totalLayers; ++i)
47	    {
48	        if (mConfig.layerTypes[i] == LayerType::kAttention)
49	        {
50	            mAbsToKVIndex[i] = kvLocalIdx++;
51	        }
52	        else
53	        {
54	            mAbsToMambaIndex[i] = mambaLocalIdx++;
55	        }
56	    }
57	
58	    // Validate that local counts match sub-manager configs.
59	    check::check(kvLocalIdx == mConfig.kvConfig.numAttentionLayers,
60	        "HybridCacheManager: number of kAttention layers in layerTypes (" + std::to_string(kvLocalIdx)
61	            + ") must equal kvConfig.numAttentionLayers (" + std::to_string(mConfig.kvConfig.numAttentionLayers)
62	            + ").");
63	    check::check(mambaLocalIdx == mConfig.mambaConfig.numRecurrentLayers,
64	        "HybridCacheManager: number of kMamba layers in layerTypes (" + std::to_string(mambaLocalIdx)
65	            + ") must equal mambaConfig.numRecurrentLayers (" + std::to_string(mConfig.mambaConfig.numRecurrentLayers)
66	            + ").");
67	
68	    // Construct sub-managers.
69	    mKVCache = KVCacheManager(mConfig.kvConfig, stream);
70	    mMambaCache = MambaCacheManager(mConfig.mambaConfig, stream);
71	
72	    // Allocate shared device KV cache lengths tensor (zero-initialised).
73	    mDeviceKVCacheLengths = rt::Tensor(
74	        {mConfig.maxBatchSize}, DeviceType::kGPU, DataType::kINT32, "HybridCacheManager::mDeviceKVCacheLengths");
75	    CUDA_CHECK(
76	        cudaMemsetAsync(mDeviceKVCacheLengths.rawPointer(), 0, mDeviceKVCacheLengths.getMemoryCapacity(), stream));
77	
78	    // Pre-build per-headDim groups for batched kernel launches.
79	    if (mKVCache.numLayers() > 0)
80	    {
81	        // Group KV layers by headDim, preserving insertion order via an auxiliary vector.
82	        std::unordered_map<int32_t, size_t> headDimToGroupIdx;
83	        for (int32_t i = 0; i < mKVCache.numLayers(); ++i)
84	        {
85	            auto const& lc = mKVCache.getLayerConfig(i);
86	            auto it = headDimToGroupIdx.find(lc.headDim);
87	            if (it == headDimToGroupIdx.end())
88	            {
89	                headDimToGroupIdx[lc.headDim] = mHeadDimGroups.size();
90	                // Positional init to satisfy -Werror=missing-field-initializers; order matches
91	                // the HeadDimGroup field declaration in hybridCacheManager.h.
92	                mHeadDimGroups.push_back(HeadDimGroup{lc.headDim, 0, 0, {}, {}, {}, {}});
93	            }
94	            size_t const gIdx = headDimToGroupIdx[lc.headDim];
95	            auto& group = mHeadDimGroups[gIdx];
96	            group.localKVIndices.push_back(i);
97	            group.maxKVHeads = std::max(group.maxKVHeads, lc.numKVHeads);
98	            group.numLayers++;
99	
100	            kernel::KVLayerInfo info{};
101	            info.data = mKVCache.getCombinedKVCache(i).rawPointer();
102	            info.numKVHeads = lc.numKVHeads;
103	            info.maxSeqLen = mConfig.kvConfig.maxSequenceLength;
104	            group.hostInfos.push_back(info);
105	        }
106	
107	        // Upload each group's layer info array to the device and pre-allocate a scratch buffer
108	        // for save/restore operations (avoids per-call cudaMalloc/cudaFree synchronisation).
109	        for (auto& group : mHeadDimGroups)
110	        {
111	            size_t const infoBytes = group.hostInfos.size() * sizeof(kernel::KVLayerInfo);
112	            group.deviceLayerInfos = rt::Tensor({static_cast<int64_t>(infoBytes)}, DeviceType::kGPU, DataType::kINT8,
113	                "HybridCacheManager::headDimGroup_" + std::to_string(group.headDim));
114	            CUDA_CHECK(cudaMemcpyAsync(group.deviceLayerInfos.rawPointer(), group.hostInfos.data(), infoBytes,
115	                cudaMemcpyHostToDevice, stream));
116	
117	            group.deviceScratchInfos = rt::Tensor({static_cast<int64_t>(infoBytes)}, DeviceType::kGPU, DataType::kINT8,
118	                "HybridCacheManager::scratchInfos_" + std::to_string(group.headDim));
119	        }
120	    }
121	
122	    LOG_DEBUG("HybridCacheManager: totalLayers=%d, kvLayers=%d, mambaLayers=%d, maxBatchSize=%d, headDimGroups=%zu",
123	        totalLayers, kvLocalIdx, mambaLocalIdx, mConfig.maxBatchSize, mHeadDimGroups.size());
124	}
