219	std::vector<HybridCacheManager::KVHeadDimGroupView> HybridCacheManager::getKVHeadDimGroups() const
220	{
221	    std::vector<KVHeadDimGroupView> views;
222	    views.reserve(mHeadDimGroups.size());
223	    for (auto const& group : mHeadDimGroups)
224	    {
225	        views.push_back(KVHeadDimGroupView{
226	            static_cast<kernel::KVLayerInfo const*>(group.deviceLayerInfos.rawPointer()),
227	            group.numLayers,
228	            group.headDim,
229	            group.maxKVHeads,
230	        });
231	    }
232	    return views;
233	}
