239	rt::Tensor& HybridCacheManager::getKVCacheLengths() noexcept
240	{
241	    return mDeviceKVCacheLengths;
242	}
243	
244	void HybridCacheManager::resetForNewSequences(rt::Tensor const& reuseKVCacheLengths, cudaStream_t stream)
245	{
246	    int32_t const batchSize = static_cast<int32_t>(reuseKVCacheLengths.getShape()[0]);
247	    check::check(
248	        batchSize <= mConfig.maxBatchSize, "Batch size of request shall not exceed the max supported batch size.");
249	    check::check(
250	        reuseKVCacheLengths.getDeviceType() == DeviceType::kCPU, "The reuseKVCacheLengths tensor shall reside on CPU.");
251	    check::check(reuseKVCacheLengths.getDataType() == mDeviceKVCacheLengths.getDataType(),
252	        "The data type of the reuseKVCacheLengths tensor shall match the data type of the Device KVCache Lengths.");
253	
254	    mActiveBatchSize = batchSize;
255	    check::check(mDeviceKVCacheLengths.reshape({mActiveBatchSize}), "Tensor reshape failed");
256	
257	    // If all reuse lengths are 0, set mKVCacheAllEmpty to true.
258	    int32_t const* reuseData = reuseKVCacheLengths.dataPointer<int32_t>();
259	    bool allEmpty{true};
260	    for (int32_t i = 0; i < batchSize; ++i)
261	    {
262	        if (reuseData[i] != 0)
263	        {
264	            allEmpty = false;
265	            break;
266	        }
267	    }
268	    mKVCacheAllEmpty = allEmpty;
269	    CUDA_CHECK(cudaMemcpyAsync(mDeviceKVCacheLengths.rawPointer(), reuseKVCacheLengths.rawPointer(),
270	        reuseKVCacheLengths.getMemoryCapacity(), cudaMemcpyHostToDevice, stream));
271	}
