273	void HybridCacheManager::commitSequenceLength(rt::Tensor const& newContextLengths, cudaStream_t stream)
274	{
275	    check::check(newContextLengths.getDataType() == DataType::kINT32,
276	        "The newContextLengths tensor shall have data type of int32_t.");
277	    check::check(
278	        newContextLengths.getDeviceType() == DeviceType::kGPU, "The newContextLengths tensor shall reside on GPU.");
279	    check::check(newContextLengths.getShape()[0] == mActiveBatchSize,
280	        "The newContextLengths tensor shall have the same batch size as the active batch size.");
281	
282	    kernel::incrementLengthTensor(mDeviceKVCacheLengths, newContextLengths, stream);
283	
284	    // No longer empty after committing a sequence length.
285	    mKVCacheAllEmpty = false;
286	}
