319	// Compaction
320	// ------------------------------------------------------------------
321	
322	void HybridCacheManager::compactBatch(
323	    rt::Tensor const& batchMapping, int32_t oldBatch, int32_t newBatch, cudaStream_t stream)
324	{
325	    // Compact KV cache layers using batched kernels — one launch per headDim group.
326	    for (auto const& group : mHeadDimGroups)
327	    {
328	        auto const* layerInfos = static_cast<kernel::KVLayerInfo const*>(group.deviceLayerInfos.rawPointer());
329	        kernel::compactKVCacheBatched(layerInfos, batchMapping, mDeviceKVCacheLengths, group.numLayers, group.headDim,
330	            mConfig.kvConfig.kvCacheType, group.maxKVHeads, mConfig.maxBatchSize, oldBatch, newBatch, stream);
331	    }
332	
333	    // Compact the shared KV cache lengths tensor separately after all layers are done.
334	    kernel::compactTensorBatch(mDeviceKVCacheLengths, batchMapping, mDeviceKVCacheLengths, oldBatch, newBatch, stream);
335	
336	    // Compact Mamba recurrent and conv states.
337	    // compactTensorBatch asserts shape[0] == oldBatch, but Mamba tensors are allocated with
338	    // shape[0] == maxBatchSize. Reshape to [oldBatch, ...] before compaction and [newBatch, ...] after.
339	    auto const& mambaConfig = mMambaCache.getConfig();
340	    for (int32_t i = 0; i < mMambaCache.numLayers(); ++i)
341	    {
342	        rt::Tensor& recState = mMambaCache.getRecurrentState(i);
343	        check::check(recState.reshape({oldBatch, mambaConfig.recurrentStateNumHeads, mambaConfig.recurrentStateHeadDim,
344	                         mambaConfig.recurrentStateSize}),
345	            "Tensor reshape failed");
346	        kernel::compactTensorBatch(recState, batchMapping, recState, oldBatch, newBatch, stream);
347	        check::check(recState.reshape({mambaConfig.maxBatchSize, mambaConfig.recurrentStateNumHeads,
348	                         mambaConfig.recurrentStateHeadDim, mambaConfig.recurrentStateSize}),
349	            "Tensor reshape failed");
350	
351	        rt::Tensor& convState = mMambaCache.getConvState(i);
352	        check::check(
353	            convState.reshape({oldBatch, mambaConfig.convDim, mambaConfig.convKernel}), "Tensor reshape failed");
354	        kernel::compactTensorBatch(convState, batchMapping, convState, oldBatch, newBatch, stream);
355	        check::check(convState.reshape({mambaConfig.maxBatchSize, mambaConfig.convDim, mambaConfig.convKernel}),
356	            "Tensor reshape failed");
357	    }
358	}
359	
360	// ------------------------------------------------------------------
361	// System prompt cache
362	// ------------------------------------------------------------------
363	
364	std::vector<rt::Tensor> HybridCacheManager::captureKVCache(
365	    int32_t batchIdx, int32_t sequenceLength, cudaStream_t stream)
366	{
367	    // The batched save/restore kernels only instantiate the `half` template today — match main's
368	    // contract of throwing loudly on unsupported dtypes instead of silently corrupting.
369	    check::check(mConfig.kvConfig.kvCacheType == nvinfer1::DataType::kHALF,
370	        "HybridCacheManager::captureKVCache currently only supports kHALF KV cache; "
371	        "FP8 system-prompt cache is not implemented.");
372	
373	    // Allocate all per-layer destination tensors first.
374	    std::vector<rt::Tensor> result;
375	    result.reserve(mKVCache.numLayers());
376	    for (int32_t i = 0; i < mKVCache.numLayers(); ++i)
377	    {
378	        KVLayerConfig const& lc = mKVCache.getLayerConfig(i);
379	        result.emplace_back(rt::Tensor({2, lc.numKVHeads, sequenceLength, lc.headDim}, DeviceType::kGPU,
380	            mConfig.kvConfig.kvCacheType, "HybridCacheManager::capturedKVCache_" + std::to_string(i)));
381	    }
382	
383	    // Batch the copies per headDim group (non-const ref: scratch buffer is overwritten).
384	    for (auto& group : mHeadDimGroups)
385	    {
386	        // Build destination KVLayerInfo array on host, then upload to pre-allocated device scratch.
387	        // The vector is pageable; cudaMemcpyAsync stages it through the runtime's internal pinned
388	        // buffer (blocking briefly for the staging), which is what makes it safe to reuse the
389	        // vector immediately on return. For KB-sized uploads the staging cost is in the microseconds.
390	        std::vector<kernel::KVLayerInfo> dstInfos(group.numLayers);
391	        for (int32_t g = 0; g < group.numLayers; ++g)
392	        {
393	            int32_t const kvIdx = group.localKVIndices[g];
394	            KVLayerConfig const& lc = mKVCache.getLayerConfig(kvIdx);
395	            dstInfos[g].data = result[kvIdx].rawPointer();
396	            dstInfos[g].numKVHeads = lc.numKVHeads;
397	            dstInfos[g].maxSeqLen = sequenceLength; // destination tensor's "maxSeqLen" == sequenceLength
398	        }
399	
400	        size_t const infoBytes = dstInfos.size() * sizeof(kernel::KVLayerInfo);
401	        CUDA_CHECK(cudaMemcpyAsync(
402	            group.deviceScratchInfos.rawPointer(), dstInfos.data(), infoBytes, cudaMemcpyHostToDevice, stream));
403	
404	        auto const* srcLayerInfos = static_cast<kernel::KVLayerInfo const*>(group.deviceLayerInfos.rawPointer());
405	        auto const* dstLayerInfos = static_cast<kernel::KVLayerInfo const*>(group.deviceScratchInfos.rawPointer());
406	
407	        kernel::saveKVCacheBatched(srcLayerInfos, dstLayerInfos, group.numLayers, group.headDim, group.maxKVHeads,
408	            mConfig.maxBatchSize, batchIdx, sequenceLength, stream);
409	    }
410	
411	    return result;
412	}
413	
414	void HybridCacheManager::restoreKVCache(std::vector<rt::Tensor> const& saved, int32_t batchIdx, cudaStream_t stream)
415	{
416	    // See captureKVCache for the dtype contract.
417	    check::check(mConfig.kvConfig.kvCacheType == nvinfer1::DataType::kHALF,
418	        "HybridCacheManager::restoreKVCache currently only supports kHALF KV cache; "
419	        "FP8 system-prompt cache is not implemented.");
420	
421	    // Batch the copies per headDim group (non-const ref: scratch buffer is overwritten).
422	    for (auto& group : mHeadDimGroups)
423	    {
424	        // Pageable staging (see captureKVCache for rationale).
425	        std::vector<kernel::KVLayerInfo> srcInfos(group.numLayers);
426	        for (int32_t g = 0; g < group.numLayers; ++g)
427	        {
428	            int32_t const kvIdx = group.localKVIndices[g];
429	            KVLayerConfig const& lc = mKVCache.getLayerConfig(kvIdx);
430	            auto const& srcShape = saved[kvIdx].getShape();
431	            srcInfos[g].data = const_cast<void*>(saved[kvIdx].rawPointer());
432	            srcInfos[g].numKVHeads = lc.numKVHeads;
433	            srcInfos[g].maxSeqLen = srcShape[2]; // sequenceLength from the saved tensor
434	        }
435	
436	        size_t const infoBytes = srcInfos.size() * sizeof(kernel::KVLayerInfo);
437	        CUDA_CHECK(cudaMemcpyAsync(
438	            group.deviceScratchInfos.rawPointer(), srcInfos.data(), infoBytes, cudaMemcpyHostToDevice, stream));
439	
440	        auto const* dstLayerInfos = static_cast<kernel::KVLayerInfo const*>(group.deviceLayerInfos.rawPointer());
441	        auto const* srcLayerInfos = static_cast<kernel::KVLayerInfo const*>(group.deviceScratchInfos.rawPointer());
442	
443	        int32_t const sequenceLength = saved[group.localKVIndices[0]].getShape()[2];
444	
445	        kernel::instantiateKVCacheBatched(dstLayerInfos, srcLayerInfos, group.numLayers, group.headDim,
446	            group.maxKVHeads, mConfig.maxBatchSize, batchIdx, sequenceLength, stream);
447	    }
448	}
