31	bool needsBaseVerifyIntermediateStates(DeploymentConfig const& bundle)
32	{
33	    if (bundle.base.numLinearAttnLayers == 0)
34	    {
35	        return false;
36	    }
37	
38	    switch (bundle.base.specDecodeType)
39	    {
40	    case SpecDecodeMode::kMTP:
41	    case SpecDecodeMode::kDFlash: return true;
42	    case SpecDecodeMode::kGemma4MTP:
43	    case SpecDecodeMode::kEAGLE:
44	    case SpecDecodeMode::kNONE: return false;
45	    }
46	    return false;
47	}
