51	bool isDFlashDDTreeShape(DeploymentConfig const& bundle)
52	{
53	    return bundle.specConfig.has_value() && bundle.base.specDecodeType == SpecDecodeMode::kDFlash
54	        && bundle.specConfig->draftingTopK > 1;
55	}
