57	int32_t baseVerifyIntermediateSeqLen(DeploymentConfig const& bundle)
58	{
59	    if (!needsBaseVerifyIntermediateStates(bundle))
60	    {
61	        return 0;
62	    }
63	    if (bundle.base.specDecodeType != SpecDecodeMode::kDFlash)
64	    {
65	        return bundle.specConfig->maxVerifySize;
66	    }
67	    return isDFlashDDTreeShape(bundle) ? bundle.specConfig->verifySize : bundle.specConfig->dflashBlockSize;
68	}
