77	std::unique_ptr<SharedResources> SharedResources::createForLLM(
78	    LLMEngineConfig const& cfg, std::unordered_map<std::string, std::string> const& loraWeightsMap, cudaStream_t stream)
79	{
80	    auto resources = std::make_unique<SharedResources>();
81	
82	    // Hybrid cache manager (attention KV + Mamba recurrent + conv states).
83	    // KVLayerConfig list is sized and populated by parseEngineConfig; its length
84	    // equals the attention-layer count and is indexed by LOCAL attention index.
85	    rt::KVCacheManager::Config kvCfg{
86	        /*.numAttentionLayers=*/static_cast<int32_t>(cfg.kvLayerConfigs.size()),
87	        /*.maxBatchSize=*/cfg.maxSupportedBatchSize,
88	        /*.maxSequenceLength=*/cfg.maxKVCacheCapacity,
89	        /*.layerConfigs=*/cfg.kvLayerConfigs,
90	        /*.kvCacheType=*/cfg.kvCacheDtype,
91	    };
92	    rt::MambaCacheManager::Config mambaCfg{
93	        /*.numRecurrentLayers=*/cfg.numLinearAttnLayers,
94	        /*.maxBatchSize=*/cfg.maxSupportedBatchSize,
95	        /*.recurrentStateNumHeads=*/cfg.recurrentStateNumHeads,
96	        /*.recurrentStateHeadDim=*/cfg.recurrentStateHeadDim,
97	        /*.recurrentStateSize=*/cfg.recurrentStateSize,
98	        /*.convDim=*/cfg.convDim,
99	        /*.convKernel=*/cfg.convKernel,
100	        /*.maxIntermediateSeqLen=*/0,
101	        /*.recurrentStateType=*/cfg.recurrentStateDtype,
102	        /*.convStateType=*/cfg.convStateDtype,
103	    };
104	    rt::HybridCacheManager::Config hybridCfg{
105	        /*.layerTypes=*/cfg.layerTypes,
106	        /*.kvConfig=*/std::move(kvCfg),
107	        /*.mambaConfig=*/std::move(mambaCfg),
108	        /*.maxBatchSize=*/cfg.maxSupportedBatchSize,
109	    };
110	    resources->cacheManagers.push_back(std::make_unique<HybridCacheManager>(hybridCfg, stream));
111	
112	    // RoPE cache
113	    // For MRope, the cache is stored in PipelineIO (initialized below).
114	    // For standard / dynamic / LongRope / NoRope, getOrCreate handles initialization.
115	    if (cfg.useDualRope)
116	    {
117	        check::check(
118	            cfg.slidingRopeConfig.type != RopeType::kLongRope && cfg.fullRopeConfig.type != RopeType::kLongRope,
119	            "LongRope is not supported with dual RoPE bindings");
120	        resources->ropePool.getOrCreate(cfg.slidingRopeConfig, cfg.slidingRotaryDim, cfg.maxKVCacheCapacity, stream);
121	        resources->ropePool.getOrCreate(cfg.fullRopeConfig, cfg.fullRotaryDim, cfg.maxKVCacheCapacity, stream);
122	    }
123	    else if (cfg.ropeConfig.type != RopeType::kMRope)
124	    {
125	        // Standard / Dynamic / LongRope / NoRope — getOrCreate handles initialization.
126	        resources->ropePool.getOrCreate(cfg.ropeConfig, cfg.rotaryDim, cfg.maxKVCacheCapacity, stream);
127	    }
128	    // MRope: handled via PipelineIO::mropeCosSin below.
129	
130	    // LoRA
131	    if (cfg.maxSupportedLoraRank > 0)
132	    {
133	        resources->loraManager = std::make_unique<LoRAManager>();
134	        for (auto const& [loraWeightsName, loraWeightsPath] : loraWeightsMap)
135	        {
136	            if (loraWeightsPath.empty())
137	            {
138	                continue;
139	            }
140	            resources->loraManager->loadWeights(loraWeightsName, loraWeightsPath, stream);
141	        }
142	    }
143	
144	    // Externalized model weights are immutable base-engine inputs. The manager
145	    // is constructed here, but file loading and engine validation are deferred
146	    // to runtime initialization with the loaded EngineExecutor.
147	    resources->externalWeightManager = std::make_unique<ExternalWeightManager>();
148	
149	    // Zero buffer — sized to the largest shape any consumer binds:
150	    //  * deepstack_embeds_* during non-prefill phases
151	    //    (batch × seqLen × hiddenSize HALF; seqLen = maxVerifyTreeSize for SpecDecode, else 1)
152	    //  * attention mask / pos ids on paths that still need a dummy bind
153	    //  * LoRA dummy weights on resetWeights paths
154	    // kvcache_start_index is now a registry-bound tensor and does not need a dummy.
155	    {
156	        int64_t const maxBatch = cfg.maxSupportedBatchSize;
157	        int64_t const deepstackSeqLen = cfg.isSpecDecodeBase ? std::max(cfg.maxVerifyTreeSize, 1) : 1;
158	        int64_t deepstackSize = 0;
159	        if (cfg.numDeepstackFeatures > 0)
160	        {
161	            deepstackSize = maxBatch * deepstackSeqLen * cfg.hiddenSize * static_cast<int64_t>(sizeof(uint16_t));
162	        }
163	        int64_t const zeroBufferBytes = std::max(deepstackSize, static_cast<int64_t>(256));
164	        allocateZeroBuffer(*resources, zeroBufferBytes);
165	    }
166	
167	    return resources;
168	}
