170	std::unique_ptr<SharedResources> SharedResources::createForSpecDecode(DeploymentConfig const& bundle,
171	    int32_t maxRuntimeBatchSize, std::unordered_map<std::string, std::string> const& loraWeightsMap,
172	    cudaStream_t stream)
173	{
174	    check::check(
175	        bundle.draft.has_value(), "SharedResources::createForSpecDecode requires DeploymentConfig.draft to be set");
176	    check::check(bundle.specConfig.has_value(),
177	        "SharedResources::createForSpecDecode requires DeploymentConfig.specConfig to be set");
178	
179	    auto resources = std::make_unique<SharedResources>();
180	
181	    int32_t const maxDraftProposalSize = bundle.specConfig->maxDraftProposalSize;
182	
183	    // Base hybrid cache manager (index 0). Hybrid spec-decode base verification
184	    // writes per-token recurrent/conv snapshots; after accept, the decoder
185	    // scatters only the accepted prefix into the persistent state pools.
186	    {
187	        int32_t const baseMaxIntermediateSeqLen = baseVerifyIntermediateSeqLen(bundle);
188	        rt::KVCacheManager::Config kvCfg{
189	            /*.numAttentionLayers=*/static_cast<int32_t>(bundle.base.kvLayerConfigs.size()),
190	            /*.maxBatchSize=*/bundle.base.maxSupportedBatchSize,
191	            /*.maxSequenceLength=*/bundle.base.maxKVCacheCapacity,
192	            /*.layerConfigs=*/bundle.base.kvLayerConfigs,
193	            /*.kvCacheType=*/bundle.base.kvCacheDtype,
194	        };
195	        rt::MambaCacheManager::Config mambaCfg{
196	            /*.numRecurrentLayers=*/bundle.base.numLinearAttnLayers,
197	            /*.maxBatchSize=*/bundle.base.maxSupportedBatchSize,
198	            /*.recurrentStateNumHeads=*/bundle.base.recurrentStateNumHeads,
199	            /*.recurrentStateHeadDim=*/bundle.base.recurrentStateHeadDim,
200	            /*.recurrentStateSize=*/bundle.base.recurrentStateSize,
201	            /*.convDim=*/bundle.base.convDim,
202	            /*.convKernel=*/bundle.base.convKernel,
203	            /*.maxIntermediateSeqLen=*/baseMaxIntermediateSeqLen,
204	            /*.recurrentStateType=*/bundle.base.recurrentStateDtype,
205	            /*.convStateType=*/bundle.base.convStateDtype,
206	        };
207	        rt::HybridCacheManager::Config hybridCfg{
208	            /*.layerTypes=*/bundle.base.layerTypes,
209	            /*.kvConfig=*/std::move(kvCfg),
210	            /*.mambaConfig=*/std::move(mambaCfg),
211	            /*.maxBatchSize=*/bundle.base.maxSupportedBatchSize,
212	        };
213	        resources->cacheManagers.push_back(std::make_unique<HybridCacheManager>(hybridCfg, stream));
214	    }
215	
216	    // Draft hybrid cache manager (index 1). Gemma4 MTP assistant reads the
217	    // base/target KV cache directly and must not allocate a draft-owned cache.
218	    if (bundle.specDecodeMode() == SpecDecodeMode::kGemma4MTP)
219	    {
220	        check::check(bundle.draft->sharesTargetKV && !bundle.draft->hasOwnKVCache,
221	            "Gemma4 MTP assistant must share target KV and must not own a draft KV cache.");
222	    }
223	    else
224	    {
225	        rt::KVCacheManager::Config kvCfg{
226	            /*.numAttentionLayers=*/static_cast<int32_t>(bundle.draft->kvLayerConfigs.size()),
227	            /*.maxBatchSize=*/bundle.draft->maxSupportedBatchSize,
228	            /*.maxSequenceLength=*/bundle.draft->maxKVCacheCapacity,
