150	    for (int32_t absIdx = 0; absIdx < static_cast<int32_t>(cfg.layerTypes.size()); ++absIdx)
151	    {
152	        if (cfg.layerTypes[absIdx] == rt::HybridCacheManager::LayerType::kAttention)
153	        {
154	            // Check if this attention layer shares KV cache from a donor layer.
155	            int32_t const donorIdx
156	                = (!cfg.kvSharingDonors.empty() && localAttnIdx < static_cast<int32_t>(cfg.kvSharingDonors.size()))
157	                ? cfg.kvSharingDonors[localAttnIdx]
158	                : -1;
159	
160	            // Plugin (combined KV): bind to donor's tensor if shared, else own tensor.
161	            auto& combinedKV
162	                = (donorIdx >= 0) ? kvMgr.getCombinedKVCache(donorIdx) : kvMgr.getCombinedKVCache(localAttnIdx);
163	            map.set(binding_names::formatKVCacheName(localAttnIdx, /*isPast=*/true), combinedKV);
164	            map.set(binding_names::formatKVCacheName(localAttnIdx, /*isPast=*/false), combinedKV); // alias: in-place
165	            ++localAttnIdx;
166	        }
167	        else if (cfg.layerTypes[absIdx] == rt::HybridCacheManager::LayerType::kMamba)
168	        {
169	            auto& rec = mambaMgr.getRecurrentState(localMambaIdx);
170	            auto& conv = mambaMgr.getConvState(localMambaIdx);
171	            map.set(binding_names::formatRecurrentStateName(localMambaIdx, /*isPast=*/true), rec);
172	            map.set(binding_names::formatRecurrentStateName(localMambaIdx, /*isPast=*/false), rec);
173	            map.set(binding_names::formatConvStateName(localMambaIdx, /*isPast=*/true), conv);
174	            map.set(binding_names::formatConvStateName(localMambaIdx, /*isPast=*/false), conv);
175	            // Spec-decode hybrid base: bind the per-layer intermediate state outputs.
176	            // `hasIntermediateRecurrentStates()` is true iff the MambaCacheManager
177	            // was built with `maxIntermediateSeqLen > 0` (set by createForSpecDecode
178	            // for hybrid MTP bases). EAGLE3 base lacks recurrent layers entirely,
179	            // so this branch wouldn't fire for it regardless.
180	            if (mambaMgr.hasIntermediateRecurrentStates())
181	            {
182	                map.set(binding_names::formatIntermediateRecurrentStateName(localMambaIdx),
183	                    mambaMgr.getIntermediateRecurrentState(localMambaIdx));
184	            }
185	            if (mambaMgr.hasIntermediateConvStates())
186	            {
187	                map.set(binding_names::formatIntermediateConvStateName(localMambaIdx),
188	                    mambaMgr.getIntermediateConvState(localMambaIdx));
189	            }
190	            ++localMambaIdx;
191	        }
192	        else
193	        {
194	            check::check(false, format::fmtstr("buildTensorMap: unknown LayerType at absolute layer index %d", absIdx));
195	        }
196	    }
197	
198	    // kvcache_start_index: single stable binding — the KV cache manager's
199	    // `kvCacheLengths` tensor. The registry resolves its shape from
200	    // `InferenceDims::startIndexLen` each call (0 for initial-prefill sentinel,
201	    // `batch` otherwise), so the same address serves every phase without a
202	    // per-step rebind.
203	    map.set(binding_names::kKVCacheStartIndex, cacheMgr.getKVCacheLengths());
204	
205	    // Deepstack: initial bind is the shared zero buffer (sized large enough
206	    // to cover the worst-case non-prefill shape). DeepstackBinding (owned by
207	    // the runtime) swaps to `io.deepstackEmbeds[i]` just before base prefill
208	    // and back on non-prefill phases.
209	    for (size_t i = 0; i < io.deepstackEmbeds.size(); ++i)
210	    {
211	        map.set(binding_names::formatDeepstackEmbedsName(static_cast<int32_t>(i)), res.zeroBuffer);
212	    }
213	
214	    // Hidden states output. SpecDecode base engines write their target features
215	    // into baseHiddenStates. The vanilla LLM path uses
216	    // outputHiddenStates instead (shape uses cfg.hiddenSize). Either or neither is
217	    // bound here; the engine introspection in EngineExecutor::prepare() will set
218	    // the address only if the engine actually exposes the binding.
219	    if (cfg.isSpecDecodeBase && !io.baseHiddenStates.isEmpty())
220	    {
